// Structured data builders — plain functions returning JSON-serializable objects,
// so schema is generated by code (never a plugin) and can't drift or double-encode.

const SITE_URL = 'https://elc.com.sa';

export function organizationSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'EducationalOrganization',
    name: 'ELC',
    url: SITE_URL,
    // TODO: replace with the corrected legal/GBP name once the NAP mismatch is resolved
    // ("Knowledge Edifice Institute" vs "ELC" — see plan doc section 8).
    address: {
      '@type': 'PostalAddress',
      streetAddress: '', // TODO: fill from corrected GBP listing
      addressLocality: '',
      addressCountry: 'SA',
    },
    sameAs: [
      // TODO: add YouTube, LinkedIn — currently missing per audit
    ],
  };
}

export function localBusinessSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'EducationalOrganization',
    '@id': `${SITE_URL}/#organization`,
    name: 'ELC',
    url: SITE_URL,
    // NAP must exactly match the corrected Google Business Profile listing —
    // do not fill this in until the "Knowledge Edifice Institute" vs "ELC" mismatch
    // (plan §8) is resolved with the client, or the mismatch gets baked back in.
    address: {
      '@type': 'PostalAddress',
      streetAddress: '', // TODO
      addressLocality: '', // TODO
      addressRegion: '', // TODO
      postalCode: '', // TODO
      addressCountry: 'SA',
    },
    geo: {
      '@type': 'GeoCoordinates',
      latitude: 0, // TODO — must match GBP exactly
      longitude: 0, // TODO
    },
    telephone: '', // TODO
    priceRange: '$$', // TODO — confirm band once pricing is finalized
    openingHoursSpecification: [
      // TODO — real hours, per corrected GBP listing
    ],
  };
}

export function breadcrumbSchema(items: { name: string; url: string }[]) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: item.name,
      item: item.url,
    })),
  };
}

export function courseSchema(course: {
  name: string;
  description: string;
  price: number;
  currency?: string;
  durationText: string;
  url: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Course',
    name: course.name,
    description: course.description,
    provider: { '@type': 'EducationalOrganization', name: 'ELC', sameAs: SITE_URL },
    hasCourseInstance: {
      '@type': 'CourseInstance',
      courseMode: 'Onsite',
      duration: course.durationText,
    },
    offers: {
      '@type': 'Offer',
      price: course.price,
      priceCurrency: course.currency ?? 'SAR',
      url: course.url,
    },
  };
}
